(1203, '忙个不停', 'on the go', '习语', '生活', 2, 'I have been on the go all day.', '我一整天都忙个不停。', 'adjective phrase', true, false, '/ɑn ðə ɡoʊ/', 'B2'),
(1204, '从长远来看', 'in the long run', '习语', '时间', 2, 'This will save money in the long run.', '从长远来看，这样会省钱。', 'adverb phrase', true, false, '/ɪn ðə lɔŋ rʌn/', 'B2'),
(1205, '在最后一刻', 'at the last minute', '习语', '时间', 2, 'He canceled at the last minute.', '他在最后一刻取消了。', 'adverb phrase', true, false, '/æt ðə læst ˈmɪnət/', 'B1'),
(1206, '迟做总比不做好', 'better late than never', '习语', '时间', 3, 'You finally replied; better late than never.', '你终于回复了，迟回总比不回好。', 'proverb', true, false, '/ˈbɛtər leɪt ðæn ˈnɛvər/', 'B1'),
