(1209, '很快', 'in no time', '习语', '时间', 2, 'You will feel better in no time.', '你很快就会好起来。', 'adverb phrase', true, false, '/ɪn noʊ taɪm/', 'B1'),
(1210, '到目前为止一切顺利', 'so far so good', '习语', '进展', 2, 'We have started the project; so far so good.', '我们已经开始这个项目，目前一切顺利。', 'clause', true, false, '/soʊ fɑr soʊ ɡʊd/', 'B1'),
